static UpdateInfo update;static std::thread worker;static bool busy=false,playAfter=false,playNow=false,autoFlow=false,closing=false,testing=false,readySeen=false,timeoutShown=false,managed=false;
static int selected=0,shots=0;static PROCESS_INFORMATION child{};static uint64_t launched=0,autoPlayAt=0;static std::string nonce,catalog=CatalogURL;
